from typing import Any, Callable, Dict, Optional, Set, Tuple, Type, TypeVar, Union, UnionType, List, Literal

# Define AliasPath and AliasChoices as required by the problem statement
class AliasPath:
    """Represents a path-based alias."""
    def __init__(self, path: str):
        self.path = path

    def __str__(self):
        return self.path

    def __repr__(self):
        return f"AliasPath('{self.path}')"

class AliasChoices:
    """Represents a set of allowed aliases."""
    def __init__(self, choices: Union[str, List[str]]):
        self.choices = choices

    def __str__(self):
        return str(self.choices)

    def __repr__(self):
        return f"AliasChoices({self.choices})"

